import asyncio
from app.evaluators.deterministic.finding_codes import FindingCodesCorrectnessEvaluator
from app.core.schemas import EvaluationCase, EvaluationResult, SystemExecution

class DummyCase(EvaluationCase):
    def __init__(self):
        self.expected_output = {"must_include_finding_codes": []}

class DummyExecution(SystemExecution):
    def __init__(self):
        self.output = {}

async def run_test():
    evaluator = FindingCodesCorrectnessEvaluator()
    case = DummyCase()
    execution = DummyExecution()
    result: EvaluationResult = await evaluator.evaluate(case, execution)
    assert isinstance(result, EvaluationResult)
    assert result.passed is True

def test_evaluator_handles_missing_findings():
    asyncio.run(run_test())
